function isAllowedOrigin(origin) {
  if (!origin || origin === "http://localhost:5173") return true;
  try { const u = new URL(origin); return u.protocol === "https:" && (u.hostname.endsWith(".pages.dev") || u.hostname === "business-analytics.pages.dev" || u.hostname === "ultramedix-analytics-api.islam-ahmed-solutions.workers.dev" || u.hostname.endsWith(".onrender.com")); } catch { return false; }
}
export default {
  async fetch(request, env, ctx) {
    const origin = request.headers.get("Origin"); if (origin && !isAllowedOrigin(origin)) return json({ error: "Origin not allowed" }, 403);
    const cors = { "Access-Control-Allow-Origin": origin || "null", "Access-Control-Allow-Methods": "GET, POST, OPTIONS", "Access-Control-Allow-Headers": "Content-Type", "Vary": "Origin" };
    if (request.method === "OPTIONS") return new Response(null, { status: 204, headers: cors });
    const url = new URL(request.url); const path = url.pathname;
    if ((path === "/" || path === "/index.html") && request.method === "GET") return new Response(APP_HTML, { status: 200, headers: { "Content-Type": "text/html; charset=utf-8", "Cache-Control": "no-store" } });
    if (path === "/api/health" && request.method === "GET") return json({ status: "online", service: "Business Analytics API", publicSpreadsheetAccess: true, spreadsheetConfigured: !!env.SPREADSHEET_ID, accessProtectionConfigured: false, authenticationRequired: false, businessStoreConfigured: !!env.BUSINESS_STORE }, 200, cors);
    try {
      if (!env.SPREADSHEET_ID) throw new Error("Default spreadsheet is not configured");
      if (path === "/api/businesses" && request.method === "GET") {
        const businesses = await getBusinesses(env); return json({ businesses }, 200, cors);
      }
      if (path === "/api/businesses" && request.method === "POST") {
        if (!env.BUSINESS_STORE) throw new Error("Business storage is not configured. Create a Cloudflare KV namespace and bind it as BUSINESS_STORE.");
        const body = await request.json(); if (!body.name || !body.spreadsheetUrl) throw new Error("Business name and Google Sheets link are required");
        const existing = await getBusinesses(env); if (existing.length >= 25) throw new Error("Maximum 25 businesses");
        const added = await validateBusiness(env, body.name, body.spreadsheetUrl);
        if (existing.some(b => b.spreadsheetId === added.spreadsheetId)) throw new Error("This spreadsheet is already connected");
        const saved = [...existing.filter(b => b.id !== "ultramedix"), added]; await env.BUSINESS_STORE.put("businesses", JSON.stringify(saved));
        return json({ success: true, business: added }, 201, cors);
      }
      if(path==='/api/creative-analysis'&&request.method==='GET'){
        const business=await getBusiness(env,url.searchParams.get('businessId')||'ultramedix');
        if(!business)throw Error('Business not found');
        return json(await buildCreativeReport(env,business,url.searchParams.get('start')||'',url.searchParams.get('end')||''),200,cors);
      }
      if (path === "/api/dashboard" && request.method === "GET") {
        const id = url.searchParams.get("businessId") || "ultramedix"; const business = await getBusiness(env, id); if (!business) throw new Error("Business not found");
        const startDate = url.searchParams.get("startDate") || ""; const endDate = url.searchParams.get("endDate") || "";
        const detailMode = url.searchParams.get("view")==="daily-business" ? "daily-business" : ["ads","channels","diagnostic"].includes(url.searchParams.get("details")) ? url.searchParams.get("details") : "";
        // Cache identical reports for 120s at the edge to avoid repeated expensive sheet reads.
        const key=new Request(url.toString(),{method:"GET"});
        let hit=null;try{hit=await caches.default.match(key);}catch(_){}
        if(hit)return new Response(hit.body,{status:200,headers:{"Content-Type":"application/json; charset=utf-8","Cache-Control":"no-store","X-Analytics-Cache":"EDGE",...cors}});
        // KV persists successful report JSON across edge locations and Worker instances.
        // Include business, dates and detail mode so separate report slices never collide.
        const persistentKey="dashboard-cache:v22:"+id+":"+(startDate||"all")+":"+(endDate||"all")+":"+(detailMode||"base");
        try{const persisted=await env.BUSINESS_STORE.get(persistentKey);if(persisted){
          if(ctx?.waitUntil)ctx.waitUntil(caches.default.put(key,new Response(persisted,{status:200,headers:{"Content-Type":"application/json","Cache-Control":"public,max-age=120"}})).catch(()=>{}));
          return new Response(persisted,{status:200,headers:{"Content-Type":"application/json; charset=utf-8","Cache-Control":"no-store","X-Analytics-Cache":"PERSISTENT",...cors}});
        }}catch(error){console.warn("Dashboard KV cache read error: "+String(error));}
        const report=await buildDashboard(env,business,startDate,endDate,detailMode);
        const compact=JSON.stringify(report);
        try{if(ctx?.waitUntil){
          ctx.waitUntil(caches.default.put(key,new Response(compact,{status:200,headers:{"Content-Type":"application/json; charset=utf-8","Cache-Control":"public,max-age=120"}})).catch(()=>{}));
          if(compact.length<9000000)ctx.waitUntil(env.BUSINESS_STORE.put(persistentKey,compact,{expirationTtl:300}).catch(e=>console.warn("KV report cache write failed: "+String(e))));
        }}catch(error){console.warn("Dashboard report caching failed: "+String(error));}
        return new Response(compact,{status:200,headers:{"Content-Type":"application/json; charset=utf-8","Cache-Control":"no-store","X-Analytics-Cache":"CALCULATED",...cors}});
      }
      return json({ error: "Endpoint not found" }, 404, cors);
    } catch (error) {
      return json({ error: error.message || "Internal server error" }, 500, cors);
    }
  }
};

function creativeDeliveryStatus(value){
  const status=String(value??'').trim().toLowerCase().replace(/_/g,' ');
  if(/^(active|delivering)$/.test(status))return 'active';
  if(/^(inactive|paused|archived|deleted|completed|not delivering|off|campaign paused|ad set paused|adset paused)$/.test(status))return 'inactive';
  return 'unknown';
}

// Formula-backed daily creative data. Normalization occurs once per five
// minutes per workbook, not on every date range or navigation.
const ultraCreativeSnapshots = new Map();
const ULTRA_CREATIVE_FRESH_MS = 5 * 60_000;
const ULTRA_CREATIVE_STALE_MS = 12 * 60 * 60_000;

async function readCreativeSnapshot(env,business) {
  const key = business.spreadsheetId;
  const previous = ultraCreativeSnapshots.get(key);
  const age = previous?.data ? Date.now() - previous.data.cachedAt : Infinity;
  if(previous?.data && age < ULTRA_CREATIVE_FRESH_MS) return previous.data;

  function refresh() {
    const cached = ultraCreativeSnapshots.get(key);
    if(cached?.pending) return cached.pending;
    const pending = (async()=>{
        const read=(sheet,range)=>env.readLocalOrders
          ?env.readLocalOrders(business.spreadsheetId,sheet,range,readPublicSheet)
          :readPublicSheet(business.spreadsheetId,sheet,range).then(rows=>({rows,fallback:false}));
        const mapping=parseWebsiteMapping((await read('Website Mapping and Metrics','A1:G180')).rows);
        if(!mapping.has('creativeAnalysis.range'))throw Error('Creative Analysis mapping is missing.');
        const range=mapRange(mapping,'creativeAnalysis.range');
        const {rows:raw,fallback,capturedAt}=await read(range.sheet,range.value);
        if(raw.some(r=>r.some(v=>/^#(REF!|VALUE!|ERROR!|N\/A)/.test(String(v)))))throw Error('The creative reporting formula needs attention. Check the mapped table in Meta & GA4 Reporting.');
        // Google GViz may omit or coerce the first header row. The sheet's
        // table layout is fixed within the mapped range; identify whether row zero is data
        // by its actual order-date and Ad ID instead of guessing header text.
        const first=raw[0]||[];
        const beginsWithData=Boolean(dateCandidates(first[0])[0]&&String(first[2]??"").trim());
        const dataStart=beginsWithData?0:1;
        const optional=v=>{if(v==null||String(v).trim()==='')return null;const n=Number(String(v).replace(/,/g,''));return Number.isFinite(n)?n:null;};
        const records=raw.slice(dataStart).map(r=>({date:dateCandidates(r[0])[0],name:String(r[1]||''),id:String(r[2]||''),spend:optional(r[3]),cpm:optional(r[4]),ctr:optional(r[5]),purchases:optional(r[6]),thumbnail:String(r[7]||''),messages:optional(r[9]),plays3:optional(r[10]),video25:optional(r[11]),video50:optional(r[12]),video75:optional(r[13]),video100:optional(r[14]),avgTime:optional(r[15]),videoPlays:optional(r[16]),creativeUrl:String(r[19]||''),engagements:optional(r[18]),campaign:String(r[20]||''),adset:String(r[21]||''),clicks:optional(r[22]),impressions:optional(r[23]),linkClicks:optional(r[24]),timeWeight:optional(r[26]),ctrWeight:optional(r[27]),objective:String(r[29]||'').trim(),status:creativeDeliveryStatus(r[30])})).filter(r=>r.date&&r.id);
      
      const availableFrom=records.reduce((a,r)=>!a||r.date<a?r.date:a,'');
      const availableThrough=records.reduce((a,r)=>r.date>a?r.date:a,'');
      const latestLinks=new Map();
      const remember=(index,r,field,preferTie)=>{
        const value=String(r[field]??"").trim();
        if(!r.id||!r.date||!/^https:\/\//i.test(value))return;
        const prior=index.get(r.id);
        if(!prior||r.date>prior.date||(preferTie&&r.date===prior.date))index.set(r.id,{date:r.date,[field]:value});
      };
      for(const r of records) {
        remember(latestLinks,r,"creativeUrl",false);
      }
      return {records, range:range.sheet, cachedAt:Date.now(), availableFrom,availableThrough,latestLinks,fallback,capturedAt};
    })();
    ultraCreativeSnapshots.set(key,{data:cached?.data||null,pending});
    pending.then(data=>{
      ultraCreativeSnapshots.delete(key);
      ultraCreativeSnapshots.set(key,{data,pending:null});
      while(ultraCreativeSnapshots.size>5)ultraCreativeSnapshots.delete(ultraCreativeSnapshots.keys().next().value);
      console.log("[creative-cache] Indexed",data.records.length,"records");
    },error=>{
      ultraCreativeSnapshots.set(key,{data:cached?.data||null,pending:null});
      console.warn("[creative-cache] Refresh failed",error?.message||String(error));
    });
    return pending;
  }

  if(previous?.data && age < ULTRA_CREATIVE_STALE_MS) {
    // Return immediately with last-good creative records.
    refresh().catch(()=>{});
    return previous.data;
  }
  try { return await refresh(); }
  catch(error){ if(previous?.data)return previous.data; throw error; }
}

async function buildCreativeReport(env,business,start,end){
  const {records,range,latest,latestLinks,availableFrom,availableThrough,fallback,capturedAt}=await readCreativeSnapshot(env,business);
  if(!start)start=availableFrom;
  if(!end)end=availableThrough;
  const span=Math.round((Date.parse(end)-Date.parse(start))/864e5)+1;
  if(!Number.isFinite(span)||span<1)throw Error('Choose a valid date range.');
  const prevEnd=new Date(Date.parse(start)-864e5).toISOString().slice(0,10);
  const prevStart=new Date(Date.parse(start)-span*864e5).toISOString().slice(0,10);
  const selected=records.filter(r=>r.date>=prevStart&&r.date<=end).map(r=>({
    ...r,thumbnail:r.thumbnail,
    creativeUrl:latestLinks.get(r.id)?.creativeUrl||r.creativeUrl
  }));
  return {records:selected,start,end,prevStart,prevEnd,source:range,availableFrom,availableThrough,savedData:fallback,capturedAt:capturedAt||null};
}








